	/**
	 * Whether every evaluation path of the body is already joined with a table equal to the candidate. Later optimizers
	 * move a copy along the body's required spine (e.g. {@code Join(V, LeftJoin(A, B))} becomes
	 * {@code LeftJoin(Join(V, A), B)}), so the check follows that spine: only the left side of a LeftJoin, the argument
	 * of a Filter or Extension, either side of a plain Join, and both branches of a Union.
	 */
	private static boolean joinedWithEqualTable(TupleExpr expression, ValuesSnapshot candidate, String selectorName) {
		if (expression instanceof BindingSetAssignment assignment) {
			Optional<ValuesSnapshot> snapshot = ValuesSnapshot.of(assignment, selectorName);
			return snapshot.isPresent() && snapshot.get().hasSameContent(candidate);
		}
		if (expression instanceof Join join) {
			return !join.isVariableScopeChange() && (joinedWithEqualTable(join.getLeftArg(), candidate, selectorName)
					|| joinedWithEqualTable(join.getRightArg(), candidate, selectorName));
		}
		if (expression instanceof LeftJoin leftJoin) {
			return joinedWithEqualTable(leftJoin.getLeftArg(), candidate, selectorName);
		}
		if (expression instanceof Filter filter) {
			return joinedWithEqualTable(filter.getArg(), candidate, selectorName);
		}
		if (expression instanceof Extension extension) {
			return joinedWithEqualTable(extension.getArg(), candidate, selectorName);
		}
		if (expression instanceof Union union) {
			return joinedWithEqualTable(union.getLeftArg(), candidate, selectorName)
					&& joinedWithEqualTable(union.getRightArg(), candidate, selectorName);
		}
		return false;
	}

	/**
	 * The distinct rows of a small repeatable VALUES table, inspected without consuming the table. Inspection bails out
	 * as early as possible and yields nothing for tables that cannot be copied.
	 */
	static final class ValuesSnapshot {

		private final List<String> declaredNames;
		private final List<BindingSet> distinctRows;

		private ValuesSnapshot(List<String> declaredNames, List<BindingSet> distinctRows) {
			this.declaredNames = declaredNames;
			this.distinctRows = distinctRows;
		}

		/**
		 * Returns a snapshot only for a non-empty table that is repeatable, does not bind the selector, has complete
		 * rows over exactly its declared names, and is within the row, cell and scan budgets. Single-use sources are
		 * never touched, and iteration stops at the first violation.
		 */
		static Optional<ValuesSnapshot> of(BindingSetAssignment assignment, String selectorName) {
			if (!assignment.hasRepeatableBindingSets()) {
				return Optional.empty();
			}
			List<String> names = List.copyOf(new LinkedHashSet<>(assignment.getDeclaredBindingNames()));
			if (names.isEmpty() || names.contains(selectorName) || names.size() > MAX_COPIED_CELLS) {
				return Optional.empty();
			}
			Iterable<BindingSet> source = assignment.getBindingSets();
			if (source instanceof Collection<?> collection && collection.size() > MAX_SCANNED_ROWS) {
				return Optional.empty();
			}
			Set<String> declared = new HashSet<>(names);
			Map<List<Value>, BindingSet> distinct = new LinkedHashMap<>();
			for (BindingSet row : source) {
				if (row == null) {
					return Optional.empty();
				}
				for (Binding binding : row) {
					if (binding.getValue() != null && !declared.contains(binding.getName())) {
						return Optional.empty();
					}
				}
				List<Value> values = new ArrayList<>(names.size());
				for (String name : names) {
					Value value = row.getValue(name);
					if (value == null) {
						return Optional.empty();
					}
					values.add(value);
				}
				if (!distinct.containsKey(values)) {
					int rows = distinct.size() + 1;
					if (rows > MAX_COPIED_ROWS || rows * names.size() > MAX_COPIED_CELLS) {
						return Optional.empty();
					}
					distinct.put(values, new ListBindingSet(names, values));
				}
			}
			if (distinct.isEmpty()) {
				return Optional.empty();
			}
			return Optional.of(new ValuesSnapshot(names,
					Collections.unmodifiableList(new ArrayList<>(distinct.values()))));
		}

		/** Declared names in header order. */
		List<String> declaredNames() {
			return declaredNames;
		}

		/** Rows with duplicates removed, keeping first occurrences; unmodifiable and made of stable rows. */
		List<BindingSet> distinctRows() {
			return distinctRows;
		}

		int distinctRowCount() {
			return distinctRows.size();
		}

		int cellCount() {
			return distinctRows.size() * declaredNames.size();
		}

		boolean hasSameContent(ValuesSnapshot other) {
			return new HashSet<>(declaredNames).equals(new HashSet<>(other.declaredNames))
					&& new HashSet<>(distinctRows).equals(new HashSet<>(other.distinctRows));
		}

		/** Strictly cheaper; equal cost keeps the earlier candidate. */
		private boolean isCheaperThan(ValuesSnapshot other) {
			return cellCount() < other.cellCount()
					|| cellCount() == other.cellCount() && distinctRowCount() < other.distinctRowCount();
		}
	}
